use axum::{http::StatusCode, Json};
use serde::Deserialize;

use crate::db;

#[derive(Deserialize)]
pub struct SignUp {
    pub email: String,
    pub password: String,
}

pub async fn sign_up(Json(body): Json<SignUp>) -> Result<StatusCode, StatusCode> {
    let hash = bcrypt::hash(&body.password, 12).map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    db::save_user(&body.email, &hash)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(StatusCode::CREATED)
}

